function parseAd(){const raw=$('sourceText').value,lines=raw.split(/\n+/).map(clean).filter(Boolean),phone=raw.match(/(?:\+7|8)[\d\s()-]{10,}/)?.[0]?.trim(),priceLine=lines.find(x=>/цен[аы]|₽|руб/i.test(x)),yearLine=lines.find(x=>/\b(?:19|20)\d{2}\b/.test(x)),mileageLine=lines.find(x=>/(?:т\.?\s*км|тыс|пробег|\bкм\b)/i.test(x)),locationLine=lines.find(x=>/забирать|самар|город|находится/i.test(x)),excluded=new Set([priceLine,yearLine,mileageLine,locationLine,phone&&lines.find(x=>x.includes(phone))].filter(Boolean)),modelLine=lines.find(x=>!excluded.has(x)&&!/^цена|^тел/i.test(x))||'',candidates=lines.filter(x=>x!==modelLine&&!excluded.has(x)&&!/(?:\+7|^8[\s(])/i.test(x));$('model').value=modelLine.toUpperCase().slice(0,32);$('year').value=yearLine?.match(/(?:19|20)\d{2}/)?.[0]||'';$('mileage').value=mileageLine?formatMileage(mileageLine):'';$('price').value=priceLine?formatPrice(priceLine):'';$('features').value=candidates.slice(0,6).map(x=>x.toUpperCase()).join('\n');$('location').value='Самара · Мирная, 3, корпус 1';$('phone').value='+7 927 265 17 77';save();draw();toast('Текст разобран — проверьте поля')}
function formatMileage(s){const n=s.match(/[\d\s]+/)?.[0]?.trim()||'';return /т\.?\s*км|тыс/i.test(s)?n.replace(/\s/g,'')+' 000 км':n+' км'}
function formatPrice(s){const digits=s.replace(/[^\d]/g,'');return digits?Number(digits).toLocaleString('ru-RU')+' ₽':clean(s)}
