async function addSpecialPhotos(mode,files){const limit=mode==='reviews'?3:1,current=state.specialPhotos[mode];if(!files.length||state.photoBusy||state.archiveBusy||state.exporting)return;const queue=[...files].slice(0,limit===1?1:limit-current.length);if(!queue.length)return toast('Можно добавить не более трёх отзывов');state.photoBusy=true;try{for(const file of queue){const next=await optimizedPhoto(file);if(limit===1){const old=current.splice(0,current.length,next);old.forEach(p=>URL.revokeObjectURL(p.url))}else current.push(next);renderSpecialPhotos(mode);draw();await nextFrame()}saveSpecial();toast('Фото добавлено')}catch(e){toast('Не удалось открыть фото: '+e.message)}finally{state.photoBusy=false;const input=$(mode==='reviews'?'reviewPhotos':mode+'Photos');if(input)input.value=''}}
