function renderThumbs(){window.syncSquarePhotos?.();$('photoList').innerHTML='';const collageTotal=Number($('collageCount').value);state.photos.forEach((p,i)=>{const d=document.createElement('div');d.className='thumb '+(i===state.slot?'active':'')+(p.sourceSize?' has-meta':'');d.dataset.number=i+1;d.draggable=true;const saving=p.sourceSize&&p.optimizedSize?Math.max(0,Math.round((1-p.optimizedSize/p.sourceSize)*100)):0;d.innerHTML=`<img src="${p.url}" alt="Фото ${i+1}"><button type="button" aria-label="Удалить">×</button>${p.sourceSize?`<span class="photo-meta">${formatBytes(p.optimizedSize)}${saving?` · −${saving}%`:''}</span>`:''}`;d.onclick=e=>{if(e.target.tagName==='BUTTON'){if(window.TitanPhotoLibrary)return TitanPhotoLibrary.remove(p.id);if(!confirm('Удалить фотографию из проекта и всех материалов?'))return;URL.revokeObjectURL(p.url);state.photos.splice(i,1);state.slot=Math.max(0,Math.min(state.slot,state.photos.length-1));state.page=Math.min(state.page,pages()-1);save();renderThumbs();draw();return}state.slot=i;if(i>=collageTotal)state.page=i;renderThumbs();draw()};d.ondragstart=()=>{state.dragIndex=i;d.classList.add('dragging')};d.ondragend=()=>d.classList.remove('dragging');d.ondragover=e=>e.preventDefault();d.ondrop=e=>{e.preventDefault();if(state.dragIndex===null||state.dragIndex===i)return;const moved=state.photos.splice(state.dragIndex,1)[0];state.photos.splice(i,0,moved);state.slot=i;state.dragIndex=null;save();renderThumbs();draw()};$('photoList').append(d)});updateCount()}
