function fitText(text,maxWidth,start,min=30,font='Montserrat',weight=900){let size=start;do{ctx.font=`${weight} ${size}px ${font}`;size-=2}while(ctx.measureText(text).width>maxWidth&&size>min);return size+2}
function drawCover(img,x,y,w,h,t){const scale=Math.max(w/img.width,h/img.height)*t.zoom,dw=img.width*scale,dh=img.height*scale;ctx.save();ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();ctx.filter='contrast(1.08) saturate(.88) brightness(.88)';ctx.drawImage(img,x+(w-dw)/2+t.x,y+(h-dh)/2+t.y,dw,dh);ctx.restore()}
function splitGrid(x,y,w,h,count,cols=Math.ceil(Math.sqrt(count)),gap=3){const rows=Math.ceil(count/cols),rects=[];for(let i=0;i<count;i++){const row=Math.floor(i/cols),col=i%cols,rowCount=Math.min(cols,count-row*cols),cw=(w-gap*(rowCount-1))/rowCount,ch=(h-gap*(rows-1))/rows;rects.push({x:x+col*(cw+gap),y:y+row*(ch+gap),w:cw,h:ch})}return rects}
function collageRects(count=Number($('collageCount').value),layout=$('collageLayout').value){const g=3,W=1080,H=1248;if(count===1)return[{x:0,y:0,w:W,h:H}];if(count===2)return splitGrid(0,0,W,H,2,2,g);if(count===9||count===15){const base=splitGrid(0,84,W,1080,9,3,g);return count===9?base:[...base.slice(0,7),...base.slice(7).flatMap(r=>splitGrid(r.x,r.y,r.w,r.h,4,2,g))]}if(layout==='grid')return splitGrid(0,0,W,H,count,count<=4?2:3,g);if(layout==='hero'){const heroH=690;return[{x:0,y:0,w:W,h:heroH},...splitGrid(0,heroH+g,W,H-heroH-g,count-1,count<=4?count-1:3,g)]}if(layout==='columns'){const heroW=650;return[{x:0,y:0,w:heroW,h:H},...splitGrid(heroW+g,0,W-heroW-g,H,count-1,count<=4?1:2,g)]}if(count===6)return[{x:0,y:0,w:777,h:831},{x:780,y:0,w:300,h:414},{x:780,y:417,w:300,h:414},{x:780,y:834,w:300,h:414},{x:0,y:834,w:387,h:414},{x:390,y:834,w:387,h:414}];const rightCount=Math.ceil((count-1)/2),bottomCount=count-1-rightCount,heroW=777,topH=831,rects=[{x:0,y:0,w:heroW,h:topH},...splitGrid(heroW+g,0,W-heroW-g,topH,rightCount,1,g)];if(bottomCount)rects.push(...splitGrid(0,topH+g,W,H-topH-g,bottomCount,bottomCount,g));return rects}
function placeholder(r){ctx.fillStyle='#191919';ctx.fillRect(r.x,r.y,r.w,r.h);ctx.fillStyle='#555';ctx.font='600 24px Inter';ctx.textAlign='center';ctx.fillText('+ ФОТО',r.x+r.w/2,r.y+r.h/2);ctx.textAlign='left'}
function drawPhotosRaw(){if(window.TitanWorkspace)state.page=0;if(state.page===0){const rects=collageRects();rects.forEach((r,i)=>{const p=state.storySlots?state.photos.find(p=>p.id===state.storySlots[i]):state.photos[i];p?drawCover(p.img,r.x,r.y,r.w,r.h,p.collage):placeholder(r)});if(!window.TitanWorkspace&&!state.exporting&&state.photos[state.slot]&&state.slot<rects.length){const r=rects[state.slot];ctx.strokeStyle=theme().accent;ctx.lineWidth=5;ctx.strokeRect(r.x+3,r.y+3,r.w-6,r.h-6)}}else{const p=state.photos[state.page];p?drawCover(p.img,0,0,1080,1248,p.single):placeholder({x:0,y:0,w:1080,h:1248})}}
// Keep the last unshaded photo layer stable across status and export redraws.
// One 1080×1248 buffer; any source, crop, layout or backdrop change invalidates it.
let storyPhotoLayer=null;
function drawPhotos(){
 if(window.TitanWorkspace)state.page=0;
 const key=JSON.stringify({page:window.TitanWorkspace?0:state.page,slots:state.storySlots,layout:$('collageLayout').value,count:$('collageCount').value,bg:theme().bg,selection:window.TitanWorkspace?null:[state.slot,state.exporting,theme().accent],photos:state.photos.map(p=>[p.url,p.img.src,p.collage,p.single])});
 if(storyPhotoLayer?.key===key){ctx.putImageData(storyPhotoLayer.pixels,0,0);return}
 drawPhotosRaw();storyPhotoLayer={key,pixels:ctx.getImageData(0,0,1080,1248)};
}

function logoBackgroundIsDark(){try{const data=ctx.getImageData(82,138,150,30).data;let sum=0,count=0;for(let i=0;i<data.length;i+=16){sum+=.2126*data[i]+.7152*data[i+1]+.0722*data[i+2];count++}return sum/Math.max(1,count)<145}catch{return true}}
function drawLogo(){TitanVehicleDesign.logo(ctx,canvas.width,canvas.height,{captionWithoutLogo:true})}
function wrapText(text,maxWidth,maxLines=2){const words=text.split(/\s+/),lines=[];let line='';for(const word of words){const test=(line+' '+word).trim();if(ctx.measureText(test).width<=maxWidth||!line)line=test;else{lines.push(line);line=word;if(lines.length===maxLines-1)break}}if(line&&lines.length<maxLines)lines.push(line);return lines}
