function drawProofStory(){const t=theme(),p=state.specialPhotos.proof[0];ctx.fillStyle=t.bg;ctx.fillRect(0,0,1080,1920);const glow=ctx.createRadialGradient(950,180,10,650,300,800);glow.addColorStop(0,alpha(t.brand,.28));glow.addColorStop(1,alpha(t.bg,0));ctx.fillStyle=glow;ctx.fillRect(0,0,1080,720);drawLogo();ctx.fillStyle='#ddd';ctx.font=`500 ${fitText($('proofKicker').value.toUpperCase(),936,31,22,'Inter',500)}px Inter`;ctx.fillText($('proofKicker').value.toUpperCase(),72,305);ctx.fillStyle='#fff';ctx.font='900 66px Montserrat';wrapText($('proofTitle').value.toUpperCase(),936,2).forEach((line,i)=>ctx.fillText(line,72,395+i*70));const photoY=570,photoH=600;if(p)drawCover(p.img,0,photoY,1080,photoH,p.single);else placeholder({x:0,y:photoY,w:1080,h:photoH});const fade=ctx.createLinearGradient(0,photoY,0,photoY+photoH);fade.addColorStop(0,alpha(t.bg,.1));fade.addColorStop(.72,alpha(t.bg,.15));fade.addColorStop(1,t.bg);ctx.fillStyle=fade;ctx.fillRect(0,photoY,1080,photoH);ctx.fillStyle='#fff';ctx.font='800 39px Montserrat';wrapText($('proofService').value.toUpperCase(),936,2).forEach((line,i)=>ctx.fillText(line,72,1195+i*47));ctx.fillStyle=t.brand;ctx.fillRect(72,1305,90,6);['proofPoint1','proofPoint2','proofPoint3','proofPoint4'].forEach((id,i)=>{const y=1390+i*92;ctx.strokeStyle=t.brand;ctx.lineWidth=5;ctx.beginPath();ctx.arc(96,y-9,16,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#eee';ctx.font=`600 ${fitText($(id).value,850,29,21,'Inter',600)}px Inter`;ctx.fillText($(id).value,142,y)});ctx.fillStyle=t.brand;roundRect(72,1735,936,92,24);ctx.fill();ctx.fillStyle='#fff';ctx.font=`800 ${fitText($('proofCta').value,860,27,19,'Inter',800)}px Inter`;ctx.textAlign='center';ctx.fillText($('proofCta').value,540,1793);ctx.textAlign='left'}
function drawSpecialStory(){({client:drawClientStory,reviews:drawReviewsStory,proof:drawProofStory}[state.contentMode]||drawClientStory)();updateCount()}
function draw(){
 const h=state.contentMode==='client'&&clientSquare()?1080:1920;if(canvas.height!==h)canvas.height=h;
  ctx.setTransform(1,0,0,1,0,0);ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';ctx.filter='none';ctx.shadowBlur=0;ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.letterSpacing='0px';
  const t=theme();ctx.clearRect(0,0,1080,1920);ctx.fillStyle=t.bg;ctx.fillRect(0,0,1080,1920);if(state.contentMode==='proof'&&isPromoPage()){drawPromo();updateCount();return}if(state.contentMode!=='vehicle'){drawSpecialStory();return}if(isPromoPage()){drawPromo();updateCount();return}drawPhotos();if($('soldMode').checked){drawSoldStory();window.TitanPublication?.draw(ctx,1080,1920);return}TitanVehicleDesign.panel(ctx,1080,1920,{story:true});updateCount();
}

function transformAt(x,y){if(isPromoPage())return null;if(state.contentMode!=='vehicle'){if(state.contentMode==='reviews'||state.contentMode==='proof'&&(y<570||y>1170))return null;return state.contentMode==='client'?clientCrop():specialPhoto()?.single}if(state.page>0)return y>=0&&y<=1248?state.photos[state.page]?.single:null;const rects=collageRects(),i=rects.findIndex(r=>x>=r.x&&x<=r.x+r.w&&y>=r.y&&y<=r.y+r.h);if(i>=0&&state.photos[i]){state.slot=i;renderThumbs();return state.photos[i].collage}return null}
function filename(page=state.page){if(state.contentMode==='proof'&&isPromoPage())return 'titan-auto-final.png';if(state.contentMode!=='vehicle')return`titan-auto-${({client:'pokupka',reviews:'otzyvy',proof:'pruf'}[state.contentMode]||'story')}.png`;const base=`titan-auto-${($('model').value||'story').toLowerCase().replace(/[^a-zа-яё0-9]+/gi,'-')}`;return isPromoPage(page)?`${base}-final.png`:`${base}-${page+1}.png`}
async function canvasBlob(){await window.TitanInitialized;await window.TitanFormats?.ready();draw();return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Не удалось создать PNG')),'image/png',1))}
function triggerDownload(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';document.body.appendChild(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(url)},2500)}
async function downloadPage(page=state.page){if(state.exporting||state.photoBusy||state.archiveBusy)return toast('Дождитесь завершения текущей операции');const old=state.page;try{state.page=page;state.exporting=true;draw();const blob=await canvasBlob();triggerDownload(blob,filename(page));toast('Скачана текущая сторис')}catch(e){toast('Не удалось скачать: '+e.message)}finally{state.exporting=false;state.page=old;draw()}}
const crcTable=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xEDB88320^(c>>>1):c>>>1;t[n]=c>>>0}return t})();
function crc32(bytes){let c=0xFFFFFFFF;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return(c^0xFFFFFFFF)>>>0}
function zipFiles(entries){const enc=new TextEncoder(),locals=[],centrals=[];let offset=0;for(const entry of entries){const name=enc.encode(entry.name),data=entry.data,crc=crc32(data),local=new Uint8Array(30+name.length+data.length),lv=new DataView(local.buffer);lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x800,true);lv.setUint32(14,crc,true);lv.setUint32(18,data.length,true);lv.setUint32(22,data.length,true);lv.setUint16(26,name.length,true);local.set(name,30);local.set(data,30+name.length);locals.push(local);const central=new Uint8Array(46+name.length),cv=new DataView(central.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);central.set(name,46);centrals.push(central);offset+=local.length}const centralSize=centrals.reduce((s,x)=>s+x.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,entries.length,true);ev.setUint16(10,entries.length,true);ev.setUint32(12,centralSize,true);ev.setUint32(16,offset,true);return new Blob([...locals,...centrals,end],{type:'application/zip'})}
async function downloadAll(){if(state.exporting||state.photoBusy||state.archiveBusy)return toast('Дождитесь завершения текущей операции');const old=state.page,files=[];try{state.exporting=true;for(let i=0;i<pages();i++){state.page=i;draw();const blob=await canvasBlob();files.push(new File([blob],filename(i),{type:'image/png'}))}if(navigator.share&&navigator.canShare?.({files})){await navigator.share({files,title:'Сторис ТИТАН АВТО'});toast(`Готово: ${files.length} сторис`)}else{files.forEach((file,i)=>setTimeout(()=>triggerDownload(file,file.name),i*350));toast(`Сохраняются ${files.length} PNG`)}}catch(e){if(e.name!=='AbortError')toast('Не удалось сохранить: '+e.message)}finally{state.exporting=false;state.page=old;draw()}}
function collectEditorData(){const d={};fields.forEach(id=>d[id]=$(id).value);settingFields.forEach(id=>d[id]=$(id).value);checkboxFields.forEach(id=>d[id]=$(id).checked);toggleFields.forEach(id=>d[toggleId(id)]=$(toggleId(id)).checked);return d}
function applyEditorData(d={}){d=TitanSafety.editor(d);fields.forEach(id=>{if(d[id]!=null)$(id).value=d[id]});settingFields.forEach(id=>{if(d[id]!=null)$(id).value=d[id]});checkboxFields.forEach(id=>{if(typeof d[id]==='boolean')$(id).checked=d[id]});toggleFields.forEach(id=>{if(typeof d[toggleId(id)]==='boolean')$(toggleId(id)).checked=d[toggleId(id)]});syncSettingsUi();updatePromoPanel();syncUiTheme()}
function setBatchStatus(text,type=''){$('batchStatus').textContent=text;$('batchStatus').className='batch-status'+(type?' '+type:'')}
function markBatchDirty(){if(state.workMode!=='batch'||state.batchBusy)return;state.batchDirty=true;setBatchStatus('Есть несохранённые изменения','dirty')}
function save(){if(state.workMode==='batch'){markBatchDirty();return}TitanSafety.storage.set('titan-story-data',JSON.stringify(collectEditorData()))}
let batchDbPromise=null,batchStorageFallback=false;const batchMemory=new Map();
function openBatchDb(){if(batchStorageFallback)return Promise.resolve(null);if(batchDbPromise)return batchDbPromise;batchDbPromise=new Promise(resolve=>{let settled=false;const fallback=()=>{if(settled)return;settled=true;clearTimeout(timer);batchStorageFallback=true;window.dispatchEvent(new Event('titan-storage-error'));resolve(null)},timer=setTimeout(fallback,5000);try{const request=indexedDB.open('titan-auto-batch',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('vehicles'))request.result.createObjectStore('vehicles',{keyPath:'id'})};request.onsuccess=()=>{if(settled){request.result.close();return}settled=true;clearTimeout(timer);request.result.onversionchange=()=>{request.result.close();batchDbPromise=null};resolve(request.result)};request.onerror=request.onblocked=fallback}catch{fallback()}});return batchDbPromise}
function batchWrite(db,action){return new Promise((resolve,reject)=>{const tx=db.transaction('vehicles','readwrite');tx.oncomplete=()=>resolve();tx.onabort=tx.onerror=()=>reject(tx.error||Error('Подборка не сохранена'));action(tx.objectStore('vehicles'))})}
async function batchPut(record){const db=await openBatchDb();if(!db){batchMemory.set(record.id,record);return}await batchWrite(db,store=>store.put(record))}
async function batchGet(id){const db=await openBatchDb();if(!db)return batchMemory.get(id)||null;return new Promise((resolve,reject)=>{const req=db.transaction('vehicles').objectStore('vehicles').get(id);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error)})}
async function batchAll(){const db=await openBatchDb();if(!db)return[...batchMemory.values()];return new Promise((resolve,reject)=>{const req=db.transaction('vehicles').objectStore('vehicles').getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error)})}
async function batchDelete(id){const db=await openBatchDb();if(!db){batchMemory.delete(id);return}await batchWrite(db,store=>store.delete(id))}
function batchId(){return crypto.randomUUID?.()||`auto-${Date.now()}-${Math.random().toString(16).slice(2)}`}
function photoData(p){return{id:p.id=stablePhotoId(p.id),formats:TitanSafety.photoFormats(p.formats),file:p.file,sourceName:p.sourceName,sourceSize:p.sourceSize,optimizedSize:p.optimizedSize,width:p.width,height:p.height,collage:{...p.collage},single:{...p.single}}}
function currentBatchRecord(id=state.batchActiveId||batchId(),createdAt=Date.now()){return{id,createdAt,updatedAt:Date.now(),editor:collectEditorData(),photos:state.photos.map(photoData),formats:window.TitanFormats?.snapshot()}}
async function hydratePhotos(items=[]){if(!Array.isArray(items)||items.length>15)throw Error('Неверная подборка фото');const loaded=[];try{for(const item of items){const file=await TitanSafety.checkFile(item.file instanceof File?item.file:new File([item.file],item.sourceName||'photo.jpg',{type:item.file?.type||'image/jpeg'})),url=URL.createObjectURL(file);let img;try{img=await loadPhotoImage(url)}catch(e){URL.revokeObjectURL(url);throw e}loaded.push({id:stablePhotoId(item.id),file,url,img,sourceName:TitanSafety.text(item.sourceName)||file.name,sourceSize:Number(item.sourceSize)||file.size,optimizedSize:file.size,width:img.width,height:img.height,formats:TitanSafety.photoFormats(item.formats),collage:TitanSafety.crop(item.collage),single:TitanSafety.crop(item.single)})}return loaded}catch(e){loaded.forEach(p=>URL.revokeObjectURL(p.url));throw e}}
function releaseCurrentPhotos(){state.photos.forEach(p=>URL.revokeObjectURL(p.url));state.photos=[]}
async function loadBatchRecord(record,makeActive=true){if(!record)return;const nextPhotos=await hydratePhotos(record.photos);releaseCurrentPhotos();state.photos=nextPhotos;applyEditorData(record.editor);window.TitanFormats?.restoreSettings(record.formats);state.page=0;state.slot=0;state.projectId=null;state.projectDir=null;if(makeActive){state.batchActiveId=record.id;TitanSafety.storage.set('titan-batch-active',record.id)}state.batchDirty=false;renderThumbs();draw()}
function batchEditorForNewVehicle(){const d={...collectEditorData()};['sourceText','model','trim','year','mileage','volume','fuel','drive','gearbox','power','price','salePrice','features'].forEach(id=>d[id]='');d.soldMode=false;d.availableStatusLabel='';d.soldDays='10';d.textPreset='default';d.arrivalLabel='В ПРОДАЖЕ';d.cta=textPresets.default.cta;return d}
async function renderBatchVehicles(){const records=(await batchAll()).sort((a,b)=>a.createdAt-b.createdAt),list=$('batchVehicleList');list.innerHTML='';records.forEach((record,index)=>{const card=document.createElement('div'),main=document.createElement('button'),remove=document.createElement('button'),title=[record.editor?.model||`Автомобиль ${index+1}`,record.editor?.year].filter(Boolean).join(' ');card.className='batch-vehicle'+(record.id===state.batchActiveId?' active':'');main.type='button';main.className='batch-vehicle-main';main.innerHTML=`<span class="batch-vehicle-title">${title.replace(/[<>&]/g,s=>({'<':'&lt;','>':'&gt;','&':'&amp;'}[s]))}</span><span class="batch-vehicle-meta">${record.photos?.length||0} фото${record.editor?.soldMode?' · ПРОДАНО':''}${record.id===state.batchActiveId?' · редактируется':''}</span>`;main.onclick=()=>switchBatchVehicle(record.id);remove.type='button';remove.className='batch-vehicle-remove';remove.textContent='×';remove.title='Удалить из подборки';remove.onclick=()=>removeBatchVehicle(record.id);card.append(main,remove);list.append(card)});$('exportBatchBtn').disabled=!records.length||state.batchBusy;setBatchStatus(state.batchDirty?'Есть несохранённые изменения':records.length?`${records.length} авто в подборке · ${batchStorageFallback?'только в этой вкладке, скачайте JSON':'данные хранятся локально'}`:'Подборка пока пуста',state.batchDirty?'dirty':'')}
function setBatchBusy(busy,text=''){state.batchBusy=busy;['singleModeBtn','batchModeBtn','newBatchVehicleBtn','saveBatchVehicleBtn','exportBatchBtn'].forEach(id=>$(id).disabled=busy);if(text)setBatchStatus(text,'busy')}
async function saveActiveBatchVehicle(showToast=false){if(state.workMode!=='batch'||!state.batchActiveId)return;const previous=await batchGet(state.batchActiveId),record=currentBatchRecord(state.batchActiveId,previous?.createdAt||Date.now());await batchPut(record);state.batchDirty=false;await renderBatchVehicles();if(showToast)toast(batchStorageFallback?'Только в памяти — скачайте JSON':'Автомобиль сохранён в подборке')}
async function switchBatchVehicle(id){if(state.batchBusy||id===state.batchActiveId)return;try{setBatchBusy(true,'Сохраняю текущий автомобиль…');await saveActiveBatchVehicle();const record=await batchGet(id);setBatchStatus('Открываю автомобиль…','busy');await loadBatchRecord(record);await renderBatchVehicles()}catch(e){toast('Не удалось переключить автомобиль: '+e.message)}finally{setBatchBusy(false)}}
async function newBatchVehicle(){if(state.batchBusy)return;try{setBatchBusy(true,'Сохраняю текущий автомобиль…');await saveActiveBatchVehicle();const editor=batchEditorForNewVehicle(),record={id:batchId(),createdAt:Date.now(),updatedAt:Date.now(),editor,photos:[]};await batchPut(record);await loadBatchRecord(record);await renderBatchVehicles();toast('Добавлен новый автомобиль')}catch(e){toast('Не удалось добавить автомобиль: '+e.message)}finally{setBatchBusy(false)}}
async function removeBatchVehicle(id){if(state.batchBusy||!confirm('Удалить этот автомобиль из пакетной подборки?'))return;try{setBatchBusy(true,'Удаляю автомобиль…');await batchDelete(id);const records=(await batchAll()).sort((a,b)=>a.createdAt-b.createdAt);if(id===state.batchActiveId){if(records.length)await loadBatchRecord(records[0]);else{const record={id:batchId(),createdAt:Date.now(),updatedAt:Date.now(),editor:batchEditorForNewVehicle(),photos:[]};await batchPut(record);await loadBatchRecord(record)}}await renderBatchVehicles()}catch(e){toast('Не удалось удалить автомобиль: '+e.message)}finally{setBatchBusy(false)}}
function syncWorkflowUi(){const batch=state.workMode==='batch';$('singleModeBtn').classList.toggle('active',!batch);$('batchModeBtn').classList.toggle('active',batch);$('batchManager').hidden=!batch;$('downloadBtn').textContent=state.contentMode==='vehicle'?(batch?'Сохранить сторис текущего':'Сохранить все сторис'):'Скачать сторис'}
async function setWorkMode(mode){if(state.batchBusy||state.photoBusy||state.archiveBusy||state.exporting||mode===state.workMode)return;const previousMode=state.workMode,previousActive=state.batchActiveId;try{setBatchBusy(true,mode==='batch'?'Открываю пакетный режим…':'Сохраняю подборку…');if(mode==='batch'){state.singleDraft=window.TitanProject?TitanProject.snapshot():{editor:collectEditorData(),photos:state.photos.map(photoData),formats:window.TitanFormats?.snapshot()};state.workMode='batch';syncWorkflowUi();const records=(await batchAll()).sort((a,b)=>a.createdAt-b.createdAt);if(records.length){const preferredId=TitanSafety.storage.get('titan-batch-active'),preferred=preferredId?await batchGet(preferredId):null;await loadBatchRecord(preferred||records[0])}else{const record=currentBatchRecord(batchId(),Date.now());state.batchActiveId=record.id;await batchPut(record);state.batchDirty=false}await renderBatchVehicles()}else{await saveActiveBatchVehicle();state.workMode='single';syncWorkflowUi();if(state.singleDraft){await TitanProject.restore(state.singleDraft)}setBatchStatus('Подборка сохранена локально')}}catch(e){console.error(e);state.workMode=previousMode;state.batchActiveId=previousActive;syncWorkflowUi();toast('Не удалось переключить режим: '+e.message)}finally{setBatchBusy(false)}}
async function exportBatchMains(){if(state.batchBusy)return;const activeId=state.batchActiveId;try{setBatchBusy(true,'Сохраняю текущий автомобиль…');await saveActiveBatchVehicle();const records=(await batchAll()).sort((a,b)=>a.createdAt-b.createdAt),chunkSize=12,totalParts=Math.ceil(records.length/chunkSize);state.exporting=true;for(let start=0;start<records.length;start+=chunkSize){const entries=[],part=Math.floor(start/chunkSize)+1,end=Math.min(records.length,start+chunkSize);for(let i=start;i<end;i++){setBatchStatus(`Создаю главные сторис: ${i+1} / ${records.length}`,'busy');await loadBatchRecord(records[i],false);state.page=0;draw();const blob=await canvasBlob(),name=`${String(i+1).padStart(2,'0')} — ${safeName([records[i].editor?.model||'Автомобиль',records[i].editor?.year].filter(Boolean).join(' '))}.png`;entries.push({name,data:new Uint8Array(await blob.arrayBuffer())});await nextFrame()}const suffix=totalParts>1?` — часть ${part} из ${totalParts}`:'';triggerDownload(zipFiles(entries),`ТИТАН АВТО — главные сторис${suffix} — ${dateStamp()}.zip`);await nextFrame()}toast(`Готово: ${records.length} главных сторис${totalParts>1?` · ${totalParts} ZIP`:''}`)}catch(e){toast('Не удалось собрать подборку: '+e.message)}finally{state.exporting=false;const active=await batchGet(activeId);if(active)await loadBatchRecord(active);await renderBatchVehicles();setBatchBusy(false)}}
function setupBatchUi(){$('singleModeBtn').onclick=()=>setWorkMode('single');$('batchModeBtn').onclick=()=>setWorkMode('batch');$('newBatchVehicleBtn').onclick=newBatchVehicle;$('saveBatchVehicleBtn').onclick=()=>saveActiveBatchVehicle(true);$('exportBatchBtn').onclick=exportBatchMains;syncWorkflowUi()}
function specialData(){const data={contentMode:state.contentMode,clientShowModel:$('clientShowModel').checked};specialFields.forEach(id=>data[id]=$(id).value);return data}
