function safeName(value,fallback='Автомобиль'){return(value||fallback).replace(/[<>:"/\\|?*\x00-\x1F]/g,' ').replace(/\s+/g,' ').replace(/[. ]+$/g,'').trim().slice(0,110)||fallback}
function dateStamp(){const d=new Date(),p=n=>String(n).padStart(2,'0');return`${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())} ${p(d.getHours())}-${p(d.getMinutes())}`}
function vehicleTitle(){return safeName([$('model').value.trim()||'Автомобиль',$('year').value.trim()].filter(Boolean).join(' '))}
function ensureProjectId(){if(!state.projectId)state.projectId=safeName(`${vehicleTitle()} — ${dateStamp()}`);return state.projectId}
function storyArchiveName(page){const title=vehicleTitle(),num=String(page+1).padStart(2,'0');if(page===0)return`01 — Главная — ${title}.png`;if(isPromoPage(page))return`99 — Финальная — ${title}.png`;return`${num} — Фото ${page+1} — ${title}.png`}
function photoExtension(file){const ext=file?.name?.match(/\.[a-z0-9]{2,5}$/i)?.[0];if(ext)return ext.toLowerCase();return({'image/jpeg':'.jpg','image/png':'.png','image/webp':'.webp','image/heic':'.heic','image/avif':'.avif'})[file?.type]||'.jpg'}
function photoArchiveName(photo,index){return`${String(index+1).padStart(2,'0')} — Оптимизированное фото${photoExtension(photo.file)}`}
function fileToDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader;reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error||new Error('Не удалось прочитать фото'));reader.readAsDataURL(file)})}
function dataUrlToBlob(value){const comma=value.indexOf(',');if(comma<0)throw new Error('Повреждённые данные фото');const meta=value.slice(0,comma),payload=value.slice(comma+1),mime=meta.match(/^data:([^;,]+)/)?.[1]||'application/octet-stream',binary=/;base64/i.test(meta)?atob(payload):decodeURIComponent(payload),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return new Blob([bytes],{type:mime})}
async function buildProjectData(){const photos=[];for(let i=0;i<state.photos.length;i++){const p=state.photos[i];setArchiveStatus(`Готовлю фото для JSON: ${i+1} / ${state.photos.length}`,'busy');await nextFrame();photos.push({id:p.id=stablePhotoId(p.id),name:p.file?.name||photoArchiveName(p,i),type:p.file?.type||'image/jpeg',fileName:photoArchiveName(p,i),dataUrl:await fileToDataUrl(p.file),sourceName:p.sourceName||p.file?.name,sourceSize:p.sourceSize||p.file?.size,optimizedSize:p.optimizedSize||p.file?.size,width:p.width||p.img?.width,height:p.height||p.img?.height,collage:{...p.collage},single:{...p.single}})}return{schema:'titan-auto-story-project',version:2,id:ensureProjectId(),vehicle:vehicleTitle(),savedAt:new Date().toISOString(),editor:collectEditorData(),photos}}
function setArchiveStatus(text,type=''){$('archiveStatus').textContent=text;$('archiveStatus').className='archive-status'+(type?' '+type:'')}
function setArchiveBusy(busy){state.archiveBusy=busy;['connectFolderBtn','saveArchiveBtn','openProjectFolderBtn','downloadProjectBtn'].forEach(id=>$(id).disabled=busy)}
async function writeDirectoryFile(dir,name,data){const handle=await dir.getFileHandle(name,{create:true}),writer=await handle.createWritable();try{await writer.write(data);await writer.close()}catch(e){await writer.abort().catch(()=>{});throw e}}
async function connectArchiveFolder(){if(!window.showDirectoryPicker){setArchiveStatus('В этом браузере нет доступа к папкам. Откройте index.html в Chrome или Edge.','error');return null}try{const dir=await window.showDirectoryPicker({id:'titan-auto-ready-stories',mode:'readwrite'});state.archiveRoot=dir;state.projectDir=null;setArchiveStatus(`Подключена папка: ${dir.name}`,'connected');return dir}catch(e){if(e.name!=='AbortError')setArchiveStatus('Не удалось открыть папку: '+e.message,'error');return null}}
async function saveArchive(){if(state.archiveBusy)return;let projectDir=state.projectDir;if(!projectDir){const root=state.archiveRoot||await connectArchiveFolder();if(!root)return;const cars=await root.getDirectoryHandle('! Серии сторис одного авто',{create:true});projectDir=await cars.getDirectoryHandle(ensureProjectId(),{create:true});state.projectDir=projectDir}const oldPage=state.page;try{setArchiveBusy(true);setArchiveStatus('Готовлю JSON и исходники…','busy');const project=await buildProjectData(),photosDir=await projectDir.getDirectoryHandle('Фото',{create:true}),storiesDir=await projectDir.getDirectoryHandle('Сторис',{create:true});for(let i=0;i<state.photos.length;i++){setArchiveStatus(`Сохраняю исходники: ${i+1} / ${state.photos.length}`,'busy');await writeDirectoryFile(photosDir,project.photos[i].fileName,state.photos[i].file)}let mainBlob=null;state.exporting=true;for(let i=0;i<pages();i++){setArchiveStatus(`Создаю PNG: ${i+1} / ${pages()}`,'busy');state.page=i;draw();const blob=await canvasBlob();if(i===0)mainBlob=blob;await writeDirectoryFile(storiesDir,storyArchiveName(i),blob)}project.storyFiles=Array.from({length:pages()},(_,i)=>storyArchiveName(i));await writeDirectoryFile(projectDir,'project.json',new Blob([JSON.stringify(project,null,2)],{type:'application/json'}));if(state.archiveRoot&&mainBlob){const mains=await state.archiveRoot.getDirectoryHandle('! Главные сторис',{create:true});await writeDirectoryFile(mains,`${ensureProjectId()} — Главная.png`,mainBlob)}window.TitanFormats?.markSaved();setArchiveStatus(`Сохранено: ${projectDir.name} · ${pages()} PNG · ${state.photos.length} фото`,'connected');toast('Проект, PNG и исходники сохранены')}catch(e){setArchiveStatus('Ошибка сохранения: '+e.message,'error')}finally{state.exporting=false;state.page=oldPage;setArchiveBusy(false);draw()}}
async function photoFromProject(item,dir){let file;if(item.dataUrl){const blob=dataUrlToBlob(TitanSafety.imageData(item.dataUrl));file=new File([blob],item.name||item.fileName||'фото.jpg',{type:blob.type})}else if(dir&&item.fileName){const photosDir=await dir.getDirectoryHandle('Фото'),handle=await photosDir.getFileHandle(item.fileName);file=await handle.getFile()}else throw Error('В JSON нет встроенного фото');file=await TitanSafety.checkFile(file);const extension=({'image/jpeg':'.jpg','image/png':'.png','image/webp':'.webp','image/gif':'.gif','image/avif':'.avif','image/bmp':'.bmp'})[file.type]||'.jpg';file=new File([file],safeName(file.name).replace(/\.[^.]+$/,'')+extension,{type:file.type||'image/jpeg'});const url=URL.createObjectURL(file);try{const img=await loadPhotoImage(url);return{id:stablePhotoId(item.id),file,url,img,sourceName:item.sourceName||item.name||file.name,sourceSize:Number(item.sourceSize)||file.size,optimizedSize:file.size,width:img.width,height:img.height,collage:TitanSafety.crop(item.collage),single:TitanSafety.crop(item.single),formats:TitanSafety.photoFormats(item.formats)}}catch(e){URL.revokeObjectURL(url);throw e}}
async function loadProjectData(project,dir=null){if(state.archiveBusy||state.photoBusy||state.exporting)throw Error('Дождитесь завершения текущей операции');project=TitanSafety.project(project);const loaded=[];let committed=false,extras;const previous={full:window.TitanProject?.snapshot(),photos:state.photos,editor:collectEditorData(),page:state.page,slot:state.slot,projectId:state.projectId,projectDir:state.projectDir};setArchiveBusy(true);setArchiveStatus('Проверяю и восстанавливаю проект…','busy');try{extras=await window.TitanFormats?.prepareProject(project);for(let i=0;i<project.photos.length;i++){setArchiveStatus(`Открываю фото: ${i+1} / ${project.photos.length}`,'busy');loaded.push(await photoFromProject(project.photos[i],dir))}const oldPhotos=state.photos;state.photos=loaded;state.projectId=safeName(project.id||dir?.name||`${project.vehicle||'Автомобиль'} — ${dateStamp()}`);state.projectDir=dir;state.page=0;state.slot=0;state.pointers.clear();state.drag=state.pinch=null;applyEditorData({...state.defaultEditor,...project.editor});await window.TitanFormats?.commitProject(project,extras);save();renderThumbs();draw();committed=true;oldPhotos.forEach(p=>URL.revokeObjectURL(p.url));setArchiveStatus(`Открыт проект: ${project.vehicle||state.projectId} · ${loaded.length} фото`,'connected');window.TitanFormats?.markSaved();toast('Проект восстановлен')}catch(e){if(state.photos===loaded){if(previous.full)await TitanProject.restore(previous.full);else state.photos=previous.photos;applyEditorData(previous.editor);Object.assign(state,{page:previous.page,slot:previous.slot,projectId:previous.projectId,projectDir:previous.projectDir});renderThumbs();draw()}throw e}finally{if(!committed){loaded.forEach(p=>URL.revokeObjectURL(p.url));Object.values(extras?.special||{}).flat().forEach(p=>URL.revokeObjectURL(p.url))}setArchiveBusy(false)}}
async function openProjectFolder(){if(!window.showDirectoryPicker){setArchiveStatus('Открытие папок доступно в Chrome или Edge.','error');return}try{const dir=await window.showDirectoryPicker({id:'titan-auto-project',mode:'readwrite'}),handle=await dir.getFileHandle('project.json'),project=await TitanSafety.readJSON(await handle.getFile());await loadProjectData(project,dir)}catch(e){if(e.name!=='AbortError')setArchiveStatus('Не удалось открыть проект: '+e.message,'error')}}
